import { createSheet, ROWS } from './engine.js';

const STORAGE_KEY = 'mini-sheet-cells';
const COLUMNS = 'ABCDEFGHIJ';

const sheet = createSheet();
const grid = document.getElementById('grid');
const formula = document.getElementById('formula');
const address = document.getElementById('address');

let selected = 'A1';
let copied = null;

function buildGrid() {
  const head = grid.createTHead().insertRow();
  head.appendChild(document.createElement('th'));
  for (const col of COLUMNS) {
    const th = document.createElement('th');
    th.textContent = col;
    head.appendChild(th);
  }
  const body = grid.createTBody();
  for (let row = 1; row <= ROWS; row++) {
    const tr = body.insertRow();
    const th = document.createElement('th');
    th.textContent = row;
    tr.appendChild(th);
    for (const col of COLUMNS) {
      const td = document.createElement('td');
      td.dataset.ref = col + row;
      tr.appendChild(td);
    }
  }
}

function render() {
  for (const td of grid.querySelectorAll('td[data-ref]')) {
    const ref = td.dataset.ref;
    td.textContent = sheet.display(ref);
    td.classList.toggle('num', typeof sheet.get(ref) === 'number');
    td.classList.toggle('copied', ref === copied);
    td.classList.toggle('selected', ref === selected);
  }
}

function showSelection() {
  address.textContent = selected;
  formula.value = sheet.raw(selected);
}

// Called after any change to the cells: redraw, refresh the formula bar, and save.
function changed() {
  render();
  showSelection();
  localStorage.setItem(STORAGE_KEY, JSON.stringify(sheet.entries()));
}

function select(ref) {
  selected = ref;
  render();
  showSelection();
}

grid.addEventListener('click', (event) => {
  const td = event.target.closest('td[data-ref]');
  if (td) select(td.dataset.ref);
});

formula.addEventListener('keydown', (event) => {
  if (event.key !== 'Enter') return;
  event.preventDefault();
  sheet.set(selected, formula.value);
  const row = Number(selected.slice(1));
  if (row < ROWS) selected = selected[0] + (row + 1);
  changed();
});

document.getElementById('undo').addEventListener('click', () => {
  sheet.undo();
  changed();
});

document.getElementById('redo').addEventListener('click', () => {
  sheet.redo();
  changed();
});

document.getElementById('copy').addEventListener('click', () => {
  copied = selected;
  render();
});

document.getElementById('paste').addEventListener('click', () => {
  if (!copied) return;
  sheet.copy(copied, selected);
  changed();
});

document.getElementById('export').addEventListener('click', () => {
  const url = URL.createObjectURL(new Blob([sheet.toCSV()], { type: 'text/csv' }));
  const link = document.createElement('a');
  link.href = url;
  link.download = 'spreadsheet.csv';
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
});

buildGrid();
try {
  sheet.load(JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '{}'));
} catch {
  // Ignore saved data that is not valid JSON.
}
render();
showSelection();

input.content:
:root {
  font-family: system-ui, sans-serif;
  color: #222;
}

body {
  margin: 0;
  padding: 12px;
  background: #f4f5f7;
}

.toolbar {
  display: flex;
  gap: 6px;
  margin-bottom: 8px;
}

button {
  padding: 4px 10px;
  border: 1px solid #bbb;
  border-radius: 4px;
  background: #fff;
  cursor: pointer;
}

button:hover {
  background: #eef3ff;
}

.formula-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.address {
  min-width: 56px;
  padding: 4px 8px;
  border: 1px solid #ccc;
  background: #fff;
  font-family: monospace;
  text-align: center;
}

#formula {
  flex: 1;
  padding: 4px 8px;
  font: inherit;
  border: 1px solid #ccc;
  border-radius: 4px;
}

.sheet-wrap {
  max-height: 80vh;
  overflow: auto;
  background: #fff;
  border: 1px solid #ccc;
}

#grid {
  border-collapse: collapse;
  table-layout: fixed;
}

#grid th {
  background: #eceef2;
  border: 1px solid #ccc;
  padding: 2px 4px;
  font-weight: 600;
  user-select: none;
}

#grid thead th {
  position: sticky;
  top: 0;
  z-index: 2;
}

#grid tbody th {
  position: sticky;
  left: 0;
  z-index: 1;
  width: 40px;
  text-align: center;
}

#grid thead th:first-child {
  left: 0;
  z-index: 3;
  width: 40px;
}

#grid td {
  width: 96px;
  max-width: 96px;
  height: 22px;
  padding: 2px 4px;
  border: 1px solid #ddd;
  overflow: hidden;
  white-space: nowrap;
  cursor: cell;
}

#grid td.num {
  text-align: right;
}

#grid td.copied {
  background: #fff7d6;
}

#grid td.selected {
  outline: 2px solid #1a73e8;
  outline-offset: -2px;
  background: #e8f0fe;
}

