s.set('C6', '="x""y"'); eq('escaped quote', s.get('C6'), 'x"y');
s.set('C7', '=1/0'); eq('div0', s.get('C7'), '#DIV/0!');
s.set('C8', '=FOO(1)'); eq('name', s.get('C8'), '#NAME?');
s.set('C9', '=1+'); eq('parse', s.get('C9'), '#ERROR!');
s.set('D1', '=K1'); eq('ref out', s.get('D1'), '#REF!');
s.set('D2', '=SUM(A1:A3)'); eq('sum range', s.get('D2'), 0.1+0.2+0.3);
s.set('D3', '=AVERAGE(B1:B3)'); eq('avg skip text', s.get('D3'), 4);
s.set('D4', '=AVERAGE(E1:E2)'); eq('avg none', s.get('D4'), '#DIV/0!');
s.set('D5', '=MIN(E1:E2)'); eq('min none', s.get('D5'), 0);
s.set('D6', '=COUNT(A1:B3)'); eq('count', s.get('D6'), 3);
s.set('D7', '=IF(TRUE,1,1/0)'); eq('IF lazy', s.get('D7'), 1);
s.set('D8', '=IF(FALSE,1)'); eq('IF missing', s.get('D8'), false);
s.set('D9', '=ROUND(2.5,0)+ROUND(-2.5,0)'); eq('round half away', s.get('D9'), 0);
s.set('E1', '=ROUND(1234,-2)'); eq('round neg digits', s.get('E1'), 1200);
s.set('E2', '=ROUND(1.005,2)'); eq('round 1.005', s.get('E2'), 1.01);
s.set('E3', '=ABS(-3)'); eq('abs', s.get('E3'), 3);
s.set('E4', '="abc"="ABC"'); eq('text eq ci', s.get('E4'), true);
s.set('E5', '=1="1"'); eq('num never eq text', s.get('E5'), false);
s.set('E6', '="a"<"B"'); eq('text lt', s.get('E6'), true);
s.set('E7', '=1<"a"'); eq('num vs text lt', s.get('E7'), '#VALUE!');
s.set('E8', '=TRUE+TRUE'); eq('bool arith', s.get('E8'), 2);
s.set('E9', '=TRUE'); eq('bool get', s.get('E9'), true);
eq('bool display', s.display('E9'), 'TRUE');
// cycles
s.set('F1', '=F2'); s.set('F2', '=F1'); s.set('F3', '=F1+1'); s.set('F4', '=5');
eq('cycle', s.get('F1'), '#CYCLE!'); eq('dependent of cycle', s.get('F3'), '#CYCLE!'); eq('non-cycle', s.get('F4'), 5);
s.set('F2', '=3'); eq('cycle broken F1', s.get('F1'), 3); eq('F3 restored', s.get('F3'), 4);
s.set('G1', '=G1'); eq('self cycle', s.get('G1'), '#CYCLE!');
// copy
s.set('H1', '=A1*2'); s.set('H2', '=$A1+A$1'); s.set('H3', '=SUM(A1:A3)');
s.copy('H1', 'I3'); eq('copy relative', s.raw('I3'), '=B3*2');
s.copy('H2', 'I4'); eq('copy mixed', s.raw('I4'), '=$A2+B$1');
s.copy('H1', 'J30'); eq('copy out of area', s.get('J30'), '#REF!');
s.copy('H3', 'J1'); eq('copy range shift', s.raw('J1'), '=SUM(B1:B3)');
s.set('K1', '=A1'); // invalid column for set
EOF
